import subprocess,json,statistics,sys,hashlib
from pathlib import Path
w=Path('/tmp/birnam-authored-access');source=w/'read-bench.birnam'
source.write_text('''[Module load: #time];
[[|
let owner := Globals; [owner at: #accessBenchValue put: 7];
let operation := [:count | [[1 to: count] inject: 0 into: [:sum :i | [sum + [owner at: #accessBenchValue]]]]];
[operation value: 10];
[[1 to: 3] do: [:sample |
 [System gc]; let cpu := [16 clockNanos]; let answer := [operation value: 2000];
 [System println: [[16 clockNanos] - cpu]]; [System println: answer]
]]
] value]
''')
prefixes={'baseline':Path('/tmp/birnam-owned-globals/delivery-prefix'),'candidate':Path(sys.argv[1])}
rows=[]
for label in ['baseline','candidate','candidate','baseline']:
 r=subprocess.run([prefixes[label]/'bin/birnam',source],capture_output=True,text=True,timeout=180)
 assert r.returncode==0 and not r.stderr,(r.returncode,r.stdout,r.stderr)
 values=list(map(int,r.stdout.split()));assert values[1::2]==[14000]*3
 rows.append(dict(label=label,samples=values[::2]));print(rows[-1],flush=True)
med={label:statistics.median(x for r in rows if r['label']==label for x in r['samples']) for label in prefixes}
out=dict(rows=rows,median=med,ratio=med['candidate']/med['baseline'],prefixes={k:str(v) for k,v in prefixes.items()},source_sha256=hashlib.sha256(source.read_bytes()).hexdigest())
(w/(sys.argv[2]+'.json')).write_text(json.dumps(out,indent=2));print(out,flush=True)
